input.function:
() => {
  const results = { menuItems: [], engineCard: null };

  // 1) 7 个菜单项：主标题 / 副标题 / 徽章 是否单行
  const aside = document.querySelector('aside, [role="complementary"], nav');
  const scope = aside || document.body;
  const menuButtons = Array.from(scope.querySelectorAll('button')).filter(b => {
    const t = b.textContent || '';
    return /智能问答与查询|可视化决策报表|问数报告中心|决策数据看板|灵活查询|数据源与 Schema|系统管理/.test(t)
      && !/收起侧边栏/.test(t);
  });

  for (const btn of menuButtons) {
    const walker = document.createTreeWalker(btn, NodeFilter.SHOW_TEXT, {
      acceptNode: n => n.textContent.trim() ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_REJECT
    });
    const lines = [];
    let node;
    while ((node = walker.nextNode())) {
      const el = node.parentElement;
      const cs = getComputedStyle(el);
      const lh = parseFloat(cs.lineHeight) || parseFloat(cs.fontSize) * 1.2;
      const h = el.getBoundingClientRect().height;
      const wraps = h > lh * 1.6; // 超过约1.5倍行高视为回行
      lines.push({ text: node.textContent.trim().slice(0, 30), height: Math.round(h), lineHeight: Math.round(lh), wraps });
    }
    results.menuItems.push({
      title: (btn.textContent || '').trim().slice(0, 20),
      anyWrap: lines.some(l => l.wraps),
      lines
    });
  }

  // 2) 引擎状态卡片标题
  const all = Array.from(document.querySelectorAll('*'));
  const engineTitle = all.find(el => el.children.length === 0 === false && /引擎运行中|Ollama/.test(el.textContent || '') && (el.textContent || '').length < 60);
  // 更精确：找包含「引擎运行中」的最小元素
  let target = null;
  for (const el of all) {
    const txt = (el.textContent || '').trim();
    if (/引擎运行中/.test(txt) && txt.length <= 40) {
      if (!target || (el.textContent.length < target.textContent.length)) target = el;
    }
  }
  if (target) {
    const cs = getComputedStyle(target);
    const lh = parseFloat(cs.lineHeight) || parseFloat(cs.fontSize) * 1.2;
    const h = target.getBoundingClientRect().height;
    results.engineCard = {
      text: target.textContent.trim(),
      height: Math.round(h),
      lineHeight: Math.round(lh),
      singleLine: h <= lh * 1.5,
      whiteSpace: cs.whiteSpace,
      textOverflow: cs.textOverflow,
      overflow: cs.overflow,
      truncated: target.scrollWidth > target.clientWidth
    };
  } else {
    results.engineCard = 'not found';
  }

  return results;
}
